#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <tlhelp32.h>
#include <stdio.h>
#include <wchar.h>
#include <string.h>
#include "ra2_product_manifest.h"

static const wchar_t kSnapshot[] = L"product-state\\superweapon.snapshot";
typedef struct { DWORD object; BYTE b48, b56, b57, b58; DWORD d2C, d30, d34; } SuperEntry;
typedef struct { DWORD magic, version, pid, root; wchar_t sha[65]; SuperEntry entries[8]; } SuperSnapshot;

static DWORD find_pid(void) { HANDLE s=CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS,0); PROCESSENTRY32W e={sizeof(e)}; DWORD id=0; if(s==INVALID_HANDLE_VALUE)return 0; if(Process32FirstW(s,&e)) do { if(!_wcsicmp(e.szExeFile,L"game.exe")){HANDLE p=OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION,FALSE,e.th32ProcessID); wchar_t q[MAX_PATH]; DWORD n=MAX_PATH; if(p&&QueryFullProcessImageNameW(p,0,q,&n)&&!_wcsicmp(q,RA2_PRODUCT_GAME_PATH))id=e.th32ProcessID; if(p)CloseHandle(p);} } while(!id&&Process32NextW(s,&e)); CloseHandle(s); return id; }
static BOOL rd(HANDLE p,DWORD a,void*b,DWORD n){SIZE_T g=0;return ReadProcessMemory(p,(void*)(uintptr_t)a,b,n,&g)&&g==n;}
static BOOL wr(HANDLE p,DWORD a,const void*b,DWORD n){SIZE_T g=0;return WriteProcessMemory(p,(void*)(uintptr_t)a,b,n,&g)&&g==n;}
static BOOL readable_object(HANDLE p,DWORD obj){MEMORY_BASIC_INFORMATION m;if(!obj||(obj&3u)||obj<0x10000u||obj>0x7F000000u)return FALSE;if(!VirtualQueryEx(p,(void*)(uintptr_t)obj,&m,sizeof(m))||m.State!=MEM_COMMIT)return FALSE;if(m.Protect&(PAGE_NOACCESS|PAGE_GUARD))return FALSE;return TRUE;}
static BOOL save_snapshot(const SuperSnapshot*s){CreateDirectoryW(L"product-state",NULL);HANDLE f=CreateFileW(kSnapshot,GENERIC_WRITE,0,NULL,CREATE_ALWAYS,FILE_ATTRIBUTE_NORMAL,NULL);DWORD n=0;BOOL ok=f!=INVALID_HANDLE_VALUE&&WriteFile(f,s,sizeof(*s),&n,NULL)&&n==sizeof(*s);if(f!=INVALID_HANDLE_VALUE)CloseHandle(f);return ok;}
static BOOL load_snapshot(SuperSnapshot*s){HANDLE f=CreateFileW(kSnapshot,GENERIC_READ,FILE_SHARE_READ,NULL,OPEN_EXISTING,0,NULL);DWORD n=0;BOOL ok=f!=INVALID_HANDLE_VALUE&&ReadFile(f,s,sizeof(*s),&n,NULL)&&n==sizeof(*s)&&s->magic==0x53555750&&s->version==1&&!_wcsicmp(s->sha,RA2_PRODUCT_SHA256);if(f!=INVALID_HANDLE_VALUE)CloseHandle(f);return ok;}
static BOOL is_applied(const SuperSnapshot*saved,const SuperSnapshot*cur){for(DWORD i=0;i<8;i++){const SuperEntry*o=&saved->entries[i],*c=&cur->entries[i];if(!o->object)continue;if(o->object!=c->object||c->b48!=0||c->b57!=1||c->b58!=0||c->d30!=0||c->d34!=0)return FALSE;}return TRUE;}

int wmain(int argc,wchar_t**argv){BOOL capture=argc==2&&!_wcsicmp(argv[1],L"--capture"),status=argc==1||(argc==2&&!_wcsicmp(argv[1],L"--status")),apply=argc==2&&!_wcsicmp(argv[1],L"--apply"),restore=argc==2&&!_wcsicmp(argv[1],L"--restore");if(argc>2||(!capture&&!status&&!apply&&!restore)){wprintf(L"Usage: ra2_product_super.exe [--status|--capture|--apply|--restore]\n");return 2;}DWORD pid=find_pid();if(!pid){wprintf(L"TARGET_UNAVAILABLE\n");return 3;}DWORD access=PROCESS_QUERY_INFORMATION|PROCESS_VM_READ|((apply||restore)?PROCESS_VM_OPERATION|PROCESS_VM_WRITE:0);HANDLE p=OpenProcess(access,FALSE,pid);if(!p)return 4;DWORD root=0,array=0;if(!rd(p,RA2_PRODUCT_PLAYER_ROOT,&root,4)||!root||!rd(p,root+RA2_PRODUCT_SUPER_ARRAY_OFFSET,&array,4)||!array){CloseHandle(p);wprintf(L"SUPERWEAPONS=NOT_IN_TASK\n");return 5;}SuperSnapshot cur={0};cur.magic=0x53555750;cur.version=1;cur.pid=pid;cur.root=root;wcsncpy_s(cur.sha,65,RA2_PRODUCT_SHA256,_TRUNCATE);int valid=0;for(DWORD i=0;i<8;i++){DWORD obj=0;if(!rd(p,array+i*4,&obj,4)||!readable_object(p,obj))continue;SuperEntry*e=&cur.entries[i];e->object=obj;if(!rd(p,obj+0x48,&e->b48,1)||!rd(p,obj+0x56,&e->b56,1)||!rd(p,obj+0x57,&e->b57,1)||!rd(p,obj+0x58,&e->b58,1)||!rd(p,obj+0x2C,&e->d2C,4)||!rd(p,obj+0x30,&e->d30,4)||!rd(p,obj+0x34,&e->d34,4)){memset(e,0,sizeof(*e));continue;}wprintf(L"id%lu obj=0x%08lX ready=%u wait=%u active=%u\n",i,obj,e->b57,e->b58,e->b48);valid++;}if(capture){if(!save_snapshot(&cur)){CloseHandle(p);return 6;}wprintf(L"SUPER_SNAPSHOT_CAPTURED valid=%d WRITES=NONE\n",valid);CloseHandle(p);return valid?0:7;}if(status){SuperSnapshot old={0};BOOL exists=GetFileAttributesW(kSnapshot)!=INVALID_FILE_ATTRIBUTES;BOOL snapshotValid=exists&&load_snapshot(&old)&&old.pid==pid&&old.root==root;BOOL applied=snapshotValid&&is_applied(&old,&cur);wprintf(L"SUPER_STATUS valid=%d snapshot=%ls applied=%ls WRITES=NONE\n",valid,!exists?L"ABSENT":(snapshotValid?L"VALID":L"STALE"),applied?L"YES":L"NO");CloseHandle(p);return valid?0:7;}SuperSnapshot old;if(!load_snapshot(&old)||old.pid!=pid||old.root!=root){wprintf(L"SNAPSHOT_INVALID_OR_STALE\n");CloseHandle(p);return 8;}for(DWORD i=0;i<8;i++){SuperEntry*c=&cur.entries[i],*o=&old.entries[i];if(!o->object)continue;if(o->object!=c->object){wprintf(L"REFUSED: object %lu changed\n",i);CloseHandle(p);return 9;}if(apply&&(c->b48!=o->b48||c->b56!=o->b56||c->b57!=o->b57||c->b58!=o->b58||c->d30!=o->d30||c->d34!=o->d34)){wprintf(L"REFUSED: object %lu changed since capture\n",i);CloseHandle(p);return 10;}if(restore&&(c->b48!=0||c->b57!=1||c->b58!=0||c->d30!=0||c->d34!=0)){wprintf(L"REFUSED: object %lu is no longer in applied state\n",i);CloseHandle(p);return 11;}}DWORD now=0;if(!rd(p,0x00A40D2C,&now,4)){CloseHandle(p);return 12;}for(DWORD i=0;i<8;i++){SuperEntry*o=&old.entries[i];if(!o->object)continue;if(apply){BYTE z=0,one=1;DWORD z32=0;if(!wr(p,o->object+0x48,&z,1)||!wr(p,o->object+0x58,&z,1)||!wr(p,o->object+0x57,&one,1)||!wr(p,o->object+0x2C,&now,4)||!wr(p,o->object+0x30,&z32,4)||!wr(p,o->object+0x34,&z32,4)){CloseHandle(p);return 13;}}else{if(!wr(p,o->object+0x48,&o->b48,1)||!wr(p,o->object+0x56,&o->b56,1)||!wr(p,o->object+0x57,&o->b57,1)||!wr(p,o->object+0x58,&o->b58,1)||!wr(p,o->object+0x2C,&o->d2C,4)||!wr(p,o->object+0x30,&o->d30,4)||!wr(p,o->object+0x34,&o->d34,4)){CloseHandle(p);return 14;}}}FlushInstructionCache(p,NULL,0);if(restore)DeleteFileW(kSnapshot);wprintf(L"SUPER=%ls\n",apply?L"ON":L"OFF RESTORED");CloseHandle(p);return 0;}
